    {
      "label": "QUOTE",
      "frame": "ཀྱེ་རྡོར་རྒྱུད་བརྟག་པ་གཉིས་པ་ལས།",
      "head": "རྣམ་རྟོག་ལས་ནི་རྣམ་རྟོག་དང་། །སྲིད་པ་ཉིད་ཀྱིས་སྲིད་དག་བྱེད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྒྱ་རས་པས།",
      "head": "དྲི་མས་དྲི་མ་བཀྲུས་པ། ཁྱི་གུས་ཁྱི་གུ་འབྱིན་པ། རྟོག་པས་རྟོག་པ་དབྱུང་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "རྣམ་རྟོག་མེད་ན་ཡེ་ཤེས་མེད། །རྣམ་རྟོག་ལས་ནི་ཡེ་ཤེས་འབྱུང་། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཇི་ལྟར་འདོད་ཆགས་གདུངས་པ་ལ། །འདོད་ཆགས་ཉིད་ཀྱིས་དབྱུང་བར་བྱ། །ཇི་ལྟར་ཞེ་སྡང་འཁྲུགས་པ་ལ། །ཞེ་སྡང་ཉིད་ཀྱིས་དབྱུང་བར་བྱ། །ཇི་ལྟར་གཏི་མུག་སྲོས་པ་ལ། །གཏི་མུག་ཉིད་ཀྱིས་དབྱུང་བར་བྱ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཆོས་རྗེ་རྒྱ་རས་པས།",
      "head": "རྣམ་རྟོག་ཉོན་མོངས་ལ་སོགས་པ། །དགོས་དང་མེད་ཐབས་མེད་པར་བལྟ། །སྐྱོན་ཅན་མི་སྤང་སྲིད་དུ་སྤྱད། །དེས་ན་དགག་སྒྲུབ་གཉིས་དང་བྲལ། །",
