    {
      "label": "QUOTE",
      "frame": "རྗེ་ཕག་མོ་གྲུ་བས།",
      "head": "དགོས་དང་སྐུ་དྲིན་ཆེ་བ་བལྟ། །ཆེ་བའི་ཆེ་ལུགས་འདི་ལྟ་སྟེ། །དཀོན་མཆོག་གསུམ་ཡང་རྟོག་པ་ལ། །སྐབས་བརྒྱད་ལམ་ལྔ་རྣམ་རྟོག་སྟེ། །དབང་པོ་ལྔ་ཡང་རྣམ་རྟོག་ཡིན། །མཆོག་དང་ཐུན་མོང་རྣམ་རྟོག་ཏུ། །འཇམ་དཔལ་རོལ་པའི་མདོ་ལས་",
      "tail": "གསུངས།"
    },
    {
      "label": "QUOTE",
      "head": "དེ་བས་རྣམ་རྟོག་མེད་གྱུར་ན། །དཀར་པོས་བསམ་པ་མི་འགྲུབ་པ། །མཁའ་ལ་མེ་ཏོག་སྐྱེ་བ་མེད། །དཀར་ནག་ལྟོས་པས་གྲུབ་པའི་ཕྱིར། །དྲན་དང་ཤེས་བཞིན་བག་ཡོད་གསུམ། །དཀར་པོའི་ཕྱོགས་ཀྱི་རྩ་བ་ཡིན། །རྣམ་རྟོག་མེད་ན་རྩ་བ་ཞིག །དེ་བས་རྣམ་རྟོག་ངོ་མཚར་ཆེ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྒྱ་རས་པས།",
      "head": "མཐའ་མར་རྣམ་རྟོག་ཆོས་སྐུར་འཁྱེར། །རྣམ་རྟོག་བསྒོམ་དུ་མ་ཤར་ན། །གང་བྱས་འཁོར་བའི་རྒྱུ་འབྲས་ཡིན། །",
      "tail": ""
