      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྒྱ་རས་པས།",
      "head": "སེམས་མ་བཏུལ་བའི་སངས་རྒྱས་གང་ནའང་མེད་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཐམས་ཅད་གསང་བའི་རྒྱུད་ལས།",
      "head": "སངས་རྒྱས་ཀུན་གྱི་མ་ལུས་ནོར། །ཆོས་རྣམས་རང་གི་སེམས་སུ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "རང་སེམས་རྫོགས་པའི་སངས་རྒྱས་ཉིད། །སེམས་ཉིད་ལ་ནི་རྟོགས་པར་བྱ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྡོ་རྗེ་གུར་གྱི་རྒྱུད་ལས།",
      "head": "སེམས་གྱི་རྡོ་རྗེ་ལས་བྱུང་བས། སེམས་ཅན་སྣ་ཚོགས་རིགས་ཅན་ལ། །སེམས་ནི་བདག་གི་རྣམ་རྟོག་གིས། སྐྱེ་བོ་དྲི་མས་ནག་པོར་བྱས། །དེ་བས་རབ་ཏུ་འབད་པ་ཡིས། །སེམས་ཀྱི་རྡོ་རྗེ་རྣམ་པར་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྣལ་འབྱོར་མ་ཀུན་སྤྱོད་ལས།",
      "head": "དེས་ན་ཧེ་རུ་ཀ་དཔལ་རྒྱུད། །སེམས་རྒྱུད་དྲི་མེད་ཡིན་པར་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "དུས་ཀྱི་འཁོར་ལོར།",
      "head": "སེམས་ནི་དག་ན་མི་དེ་ཡང་ནི་རྒྱལ་བའི་དབང་པོར་འགྱུར་ཏེ་རྒྱལ་བ་གཞན་གྱི་ཅི་ཞིག་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཀླུའི་རྒྱལ་པོ་རྒྱ་མཚོས་ཞུས་པའི་མདོ་ལས།",
      "head": "རབ་འབྱོར་ཕྱིན་ཅི་ལོག་ལས་ཉོན་མོངས་པ་ཐམས་ཅད་བསྐྱེད་མོད་ཀྱི། སེམས་ཀྱི་རང་བཞིན་ནམ་ཡང་ཀུན་ནས་ཉོན་མོངས་པ་མ་",
      "tail": ""
    },
    {
